CREATE DATABASE IF NOT EXISTS imsafe_oop_local CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE imsafe_oop_local;
CREATE TABLE IF NOT EXISTS local_users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, display_name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_signed_in TIMESTAMP NULL, INDEX idx_local_users_email(email));
CREATE TABLE IF NOT EXISTS incidents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, local_user_id INT UNSIGNED NULL, reference_code VARCHAR(32) NOT NULL UNIQUE, reporter_name VARCHAR(120) NULL, contact_number VARCHAR(32) NULL, legend ENUM('Green','Orange','Red') NOT NULL, general_type VARCHAR(96) NOT NULL, specific_type VARCHAR(96) NOT NULL, summary VARCHAR(320) NOT NULL, description TEXT NOT NULL, status ENUM('received','verified','dispatched','resolved') NOT NULL DEFAULT 'received', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_incident_user FOREIGN KEY (local_user_id) REFERENCES local_users(id) ON DELETE SET NULL, INDEX idx_incident_status_created(status,created_at), INDEX idx_incident_user(local_user_id));
CREATE TABLE IF NOT EXISTS incident_locations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_id INT UNSIGNED NOT NULL UNIQUE, region_code VARCHAR(16) NOT NULL, region_name VARCHAR(160) NOT NULL, province_code VARCHAR(16) NULL, province_name VARCHAR(160) NULL, municipality_code VARCHAR(16) NOT NULL, municipality_name VARCHAR(160) NOT NULL, barangay_code VARCHAR(16) NOT NULL, barangay_name VARCHAR(160) NOT NULL, house_number VARCHAR(160) NULL, nearby_landmark VARCHAR(255) NULL, CONSTRAINT fk_location_incident FOREIGN KEY (incident_id) REFERENCES incidents(id) ON DELETE CASCADE, INDEX idx_location_barangay(barangay_code));
CREATE TABLE IF NOT EXISTS rapid_assessments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_id INT UNSIGNED NOT NULL UNIQUE, assessment_color VARCHAR(16) NOT NULL, impact_detail VARCHAR(255) NOT NULL, current_situation VARCHAR(255) NOT NULL, reporter_description TEXT NOT NULL, evidence_note VARCHAR(255) NULL, alternate_contact VARCHAR(32) NULL, email VARCHAR(255) NULL, CONSTRAINT fk_assessment_incident FOREIGN KEY (incident_id) REFERENCES incidents(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS assessment_needs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rapid_assessment_id INT UNSIGNED NOT NULL, need_label VARCHAR(160) NOT NULL, CONSTRAINT fk_need_assessment FOREIGN KEY (rapid_assessment_id) REFERENCES rapid_assessments(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS incident_details (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_id INT UNSIGNED NOT NULL, detail_key VARCHAR(80) NOT NULL, detail_value TEXT NOT NULL, CONSTRAINT fk_detail_incident FOREIGN KEY (incident_id) REFERENCES incidents(id) ON DELETE CASCADE, UNIQUE KEY uq_incident_detail(incident_id,detail_key));
CREATE TABLE IF NOT EXISTS dispatch_assignments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_id INT UNSIGNED NOT NULL, team_name VARCHAR(120) NOT NULL, assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, released_at TIMESTAMP NULL, CONSTRAINT fk_assignment_incident FOREIGN KEY (incident_id) REFERENCES incidents(id) ON DELETE CASCADE, INDEX idx_assignment_active(incident_id,released_at));
CREATE TABLE IF NOT EXISTS incident_updates (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_id INT UNSIGNED NOT NULL, status ENUM('received','verified','dispatched','resolved') NOT NULL, note TEXT NOT NULL, is_public TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_update_incident FOREIGN KEY (incident_id) REFERENCES incidents(id) ON DELETE CASCADE, INDEX idx_update_incident(incident_id,id));
